    "source": "def merge_sort(a: list[int]) -> list[int]:\n    \"\"\"Merge sort — complete Python reference (in-place merge, L/R/k).\"\"\"\n    arr = list(a)\n    sort(arr, 0, len(arr) - 1)\n    return arr\n\n\ndef sort(a: list[int], L: int, R: int) -> None:\n    if L >= R:\n        return\n    mid = (L + R) // 2\n    sort(a, L, mid)\n    sort(a, mid + 1, R)\n    merge(a, L, mid, R)\n\n\ndef merge(a: list[int], L: int, mid: int, R: int) -> None:\n    left = a[L:mid + 1]\n    right = a[mid + 1:R + 1]\n    i = 0\n    j = 0\n    k = L\n    while i < len(left) and j < len(right):\n        if left[i] <= right[j]:\n            a[k] = left[i]\n            i += 1\n            k += 1\n        else:\n            a[k] = right[j]\n            j += 1\n            k += 1\n    while i < len(left):\n        a[k] = left[i]\n        i += 1\n        k += 1\n    while j < len(right):\n        a[k] = right[j]\n        j += 1\n        k += 1\n",
