    "source": "/// Merge sort — complete Rust reference (in-place merge, lo/hi/k).\npub fn merge_sort(a: &[i64]) -> Vec<i64> {\n    let mut arr = a.to_vec();\n    let hi = arr.len() as isize - 1;\n    sort(&mut arr, 0, hi);\n    arr\n}\n\nfn sort(a: &mut [i64], lo: isize, hi: isize) {\n    if lo >= hi {\n        return;\n    }\n    let mid = (lo + hi) / 2;\n    sort(a, lo, mid);\n    sort(a, mid + 1, hi);\n    merge(a, lo as usize, mid as usize, hi as usize);\n}\n\nfn merge(a: &mut [i64], lo: usize, mid: usize, hi: usize) {\n    let left = a[lo..mid + 1].to_vec();\n    let right = a[mid + 1..hi + 1].to_vec();\n    let (mut i, mut j, mut k) = (0, 0, lo);\n    while i < left.len() && j < right.len() {\n        if left[i] <= right[j] {\n            a[k] = left[i];\n            i += 1;\n            k += 1;\n        } else {\n            a[k] = right[j];\n            j += 1;\n            k += 1;\n        }\n    }\n    while i < left.len() {\n        a[k] = left[i];\n        i += 1;\n        k += 1;\n    }\n    while j < right.len() {\n        a[k] = right[j];\n        j += 1;\n        k += 1;\n    }\n}\n",
